#!/usr/bin/env node
// Bundles a CommonJS preload and everything it requires into ONE self-contained file,
// which is what a sandboxed preload has to be: under `sandbox: true` a preload's
// `require` only knows `electron` and a few polyfilled built-ins, never a sibling file
// (docs/SPEC-DEBUGGER-SHELL-EXTENSIONS.md §5.4, Q2).
//
// Deliberately small and dependency-free, and strict about what it accepts:
//   - only string-literal `require("…")` calls are followed; any other `require(`
//     in code fails the build, because the bundle could not resolve it at runtime;
//   - relative specifiers are files of this repository; bare ones must be in
//     SANDBOX_MODULES, which the sandboxed preload's own `require` provides;
//   - CommonJS semantics are kept: one module cache, `module.exports` replaceable,
//     a circular require sees the partial exports, lazy requires inside functions
//     resolve on first call.
//
//   node scripts/bundle-preload.js            build every preload in PRELOADS
//   require("./scripts/bundle-preload").buildPreloads()
const fs = require("node:fs");
const path = require("node:path");

const REPO = path.join(__dirname, "..");

// What a sandboxed preload's `require` provides (Electron's sandbox docs).
const SANDBOX_MODULES = new Set(["electron", "events", "timers", "url"]);

// entry -> output. Outputs live under gitignored `dist/` folders next to their sources.
const PRELOADS = [
  {
    entry: "src/electron/extensions/internal/preload/index.js",
    out: "src/electron/extensions/internal/preload/dist/extension-preload.js",
  },
  {
    entry: "src/electron/shell/preload.js",
    out: "src/electron/shell/dist/preload.js",
  },
];

/** Code without comments, so a path named in prose is not a dependency. */
const stripComments = (source) =>
  source
    .replace(/\/\*[\s\S]*?\*\//g, "")
    .split("\n")
    .map((line) => (/^\s*\/\//.test(line) ? "" : line))
    .join("\n");

const resolveFile = (fromFile, specifier) => {
  const base = path.resolve(path.dirname(fromFile), specifier);
  for (const candidate of [base, `${base}.js`, path.join(base, "index.js")]) {
    if (fs.existsSync(candidate) && fs.statSync(candidate).isFile()) {
      return candidate;
    }
  }
  throw new Error(`${path.relative(REPO, fromFile)}: cannot resolve require("${specifier}")`);
};

/** @returns {{modules: Map<string, {source: string, deps: object}>, entryId: string}} */
const collect = (entryFile) => {
  const modules = new Map();
  const idOf = (file) => path.relative(REPO, file).split(path.sep).join("/");
  const visit = (file) => {
    const id = idOf(file);
    if (modules.has(id)) {
      return id;
    }
    const source = fs.readFileSync(file, "utf8");
    const record = { source, deps: {} };
    modules.set(id, record);
    const code = stripComments(source);
    const literal = /\brequire\(\s*(["'])([^"']+)\1\s*\)/g;
    const anyCall = /\brequire\(/g;
    const literals = [...code.matchAll(literal)];
    const calls = [...code.matchAll(anyCall)].length;
    if (calls !== literals.length) {
      throw new Error(`${id}: ${calls - literals.length} require() call(s) without a string literal`);
    }
    for (const [, , specifier] of literals) {
      if (specifier.startsWith(".")) {
        record.deps[specifier] = visit(resolveFile(file, specifier));
      } else if (SANDBOX_MODULES.has(specifier)) {
        record.deps[specifier] = null; // the sandboxed preload's own require
      } else {
        throw new Error(`${id}: require("${specifier}") is not available to a sandboxed preload`);
      }
    }
    return id;
  };
  const entryId = visit(entryFile);
  return { modules, entryId };
};

/** The bundle's source text for one entry. Pure apart from reading the sources. */
const bundle = (entryFile) => {
  const { modules, entryId } = collect(entryFile);
  const parts = [
    "// GENERATED by scripts/bundle-preload.js — do not edit. Source: " + entryId,
    "(function (sandboxRequire) {",
    "const definitions = {",
  ];
  for (const [id, { source, deps }] of modules) {
    parts.push(
      `${JSON.stringify(id)}: [${JSON.stringify(deps)}, function (module, exports, require) {`,
      source,
      "}],"
    );
  }
  parts.push(
    "};",
    "const cache = Object.create(null);",
    "const load = (id) => {",
    "  if (cache[id]) return cache[id].exports;",
    "  const module = { exports: {} };",
    "  cache[id] = module;",
    "  const [deps, define] = definitions[id];",
    "  const localRequire = (specifier) => {",
    "    if (!(specifier in deps)) throw new Error(`bundle: ${id} requires ${specifier}, which was not bundled`);",
    "    return deps[specifier] === null ? sandboxRequire(specifier) : load(deps[specifier]);",
    "  };",
    "  define.call(module.exports, module, module.exports, localRequire);",
    "  return module.exports;",
    "};",
    `load(${JSON.stringify(entryId)});`,
    "})(require);",
    ""
  );
  return parts.join("\n");
};

/** Write `text` to `file` atomically: parallel test processes may build at once. */
const writeAtomic = (file, text) => {
  fs.mkdirSync(path.dirname(file), { recursive: true });
  const temp = `${file}.${process.pid}.${Date.now()}.tmp`;
  fs.writeFileSync(temp, text);
  fs.renameSync(temp, file);
};

/** Build every preload; returns the output paths. */
const buildPreloads = () =>
  PRELOADS.map(({ entry, out }) => {
    const output = path.join(REPO, out);
    writeAtomic(output, bundle(path.join(REPO, entry)));
    return output;
  });

if (require.main === module) {
  for (const output of buildPreloads()) {
    console.log(`bundled ${path.relative(REPO, output)}`);
  }
}

module.exports = { bundle, collect, buildPreloads, PRELOADS, SANDBOX_MODULES };
